from json import dumps


class Tree:
    def __init__(self, label, children=None):
        self.label = label
        self.children = children if children is not None else []

    def __dict__(self):
        return {self.label: [c.__dict__() for c in sorted(self.children)]}

    def __str__(self, indent=None):
        return dumps(self.__dict__(), indent=indent)

    def __lt__(self, other):
        return self.label < other.label

    def __eq__(self, other):
        return self.__dict__() == other.__dict__()

    def from_pov(self, from_node):
        # Find path (list of node objects) from current root to the target node
        def find_path_nodes(node, target):
            if node.label == target:
                return [node]
            for c in node.children:
                p = find_path_nodes(c, target)
                if p:
                    return [node] + p
            return None

        path_nodes = find_path_nodes(self, from_node)
        if not path_nodes:
            raise ValueError("Node not found")

        # Helper to deep-clone a node, optionally excluding one child by label
        def clone_node(node, exclude_label=None):
            cloned_children = []
            for c in node.children:
                if exclude_label is not None and c.label == exclude_label:
                    continue
                cloned_children.append(clone_node(c, None))
            return Tree(node.label, cloned_children)

        # Start with clone of the target node (the new root)
        target_node = path_nodes[-1]
        new_root = clone_node(target_node, None)

        # Re-orient the edges along the path: attach parent clones as children down the chain
        prev_clone = new_root
        # iterate parents from parent of target up to original root
        # path_nodes is [root, ..., target]
        for i in range(len(path_nodes) - 2, -1, -1):
            parent_node = path_nodes[i]
            child_node = path_nodes[i + 1]
            parent_clone = clone_node(parent_node, exclude_label=child_node.label)
            prev_clone.children.append(parent_clone)
            prev_clone = parent_clone

        return new_root

    def path_to(self, from_node, to_node):
        # Reorient the tree to from_node as root (this will raise if from_node not found)
        new_root = self.from_pov(from_node)

        # Find path from new_root to to_node
        def find_path_labels(node, target):
            if node.label == target:
                return [node.label]
            for c in node.children:
                p = find_path_labels(c, target)
                if p:
                    return [node.label] + p
            return None

        path = find_path_labels(new_root, to_node)
        if not path:
            raise ValueError("Path not found")
        return path
